package com.bitewise.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="expenses") public class Expense { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="business_id",nullable=false) private Business business; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="category_id") private ExpenseCategory category; @Column(name="expense_date",nullable=false) private LocalDate expenseDate; private String description; @Column(nullable=false) private BigDecimal amount; @Column(name="expense_type",nullable=false) private String expenseType="VARIABLE"; @Column(nullable=false) private boolean recurring; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); public Expense(){} public Expense(Business b,ExpenseCategory c,LocalDate d,String desc,BigDecimal a,String type,boolean r){business=b;category=c;expenseDate=d;description=desc;amount=a;expenseType=type;recurring=r;} public UUID getId(){return id;} public Business getBusiness(){return business;} public ExpenseCategory getCategory(){return category;} public LocalDate getExpenseDate(){return expenseDate;} public String getDescription(){return description;} public BigDecimal getAmount(){return amount;} public String getExpenseType(){return expenseType;} public boolean isRecurring(){return recurring;} }
